+package com.example.contact;
+
+import org.springframework.stereotype.Service;
+
+import java.time.Instant;
+import java.util.Collections;
+import java.util.List;
+import java.util.concurrent.CopyOnWriteArrayList;
+
+/**
+ * Keeps every message sent so far, in memory, for the lifetime of the application.
+ */
+@Service
+public class ContactMessageService {
+
+    private final List<ContactMessage> messages = new CopyOnWriteArrayList<>();
+
+    public void send(String name, String email, String phone, String message) {
+        messages.add(0, new ContactMessage(name, email, phone, message, Instant.now()));
+    }
+
+    public List<ContactMessage> getMessages() {
+        return Collections.unmodifiableList(messages);
+    }
+}
