+        this.contactMessageService = contactMessageService;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        configureBinder();
+        configureSendButtonEnabling();
+
+        sendButton.addClickListener(event -> send());
+        sendButton.addClickShortcut(Key.ENTER);
+
+        add(new HorizontalLayout(nameField, emailField, phoneField), messageField, sendButton);
+
+        configureGrid();
+        refreshGrid();
+        add(grid);
+    }
+
+    private void configureBinder() {
+        nameField.setManualValidation(true);
+        emailField.setManualValidation(true);
+        phoneField.setManualValidation(true);
+        messageField.setManualValidation(true);
+
+        binder.forField(nameField)
+                .withDefaultValidator(false)
+                .withValidator(name -> name != null && !name.isBlank(), "Name is required")
+                .bind(ContactFormData::getName, ContactFormData::setName);
+
+        var emailBinding = binder.forField(emailField)
+                .withDefaultValidator(false)
+                .withValidator(this::validateEmail)
+                .bind(ContactFormData::getEmail, ContactFormData::setEmail);
+
+        binder.forField(phoneField)
+                .withDefaultValidator(false)
+                .bind(ContactFormData::getPhone, ContactFormData::setPhone);
+
+        binder.forField(messageField)
+                .withDefaultValidator(false)
+                .withValidator(message -> message != null && !message.isBlank(), "Message is required")
+                .withValidator(message -> message == null || message.length() <= 500,
+                        "Message must be at most 500 characters")
+                .bind(ContactFormData::getMessage, ContactFormData::setMessage);
+
+        phoneField.addValueChangeListener(event -> {
+            if (event.isFromClient()) {
+                emailBinding.validate();
+            }
+        });
+    }
+
+    private ValidationResult validateEmail(String email, ValueContext context) {
+        if (email != null && !email.isBlank()) {
+            return EMAIL_FORMAT_VALIDATOR.apply(email, context);
+        }
+        if (phoneField.getValue() == null || phoneField.getValue().isBlank()) {
+            return ValidationResult.error("Give an e-mail address or a phone number");
+        }
+        return ValidationResult.ok();
+    }
+
+    private void configureSendButtonEnabling() {
+        nameField.addValueChangeListener(event -> enableSendOnClientEdit(event.isFromClient()));
+        emailField.addValueChangeListener(event -> enableSendOnClientEdit(event.isFromClient()));
+        phoneField.addValueChangeListener(event -> enableSendOnClientEdit(event.isFromClient()));
+        messageField.addValueChangeListener(event -> enableSendOnClientEdit(event.isFromClient()));
+    }
+
+    private void enableSendOnClientEdit(boolean isFromClient) {
+        if (isFromClient) {
+            sendButton.setEnabled(true);
+        }
+    }
+
+    private void configureGrid() {
+        grid.addColumn(ContactMessage::name).setHeader("Name");
+        grid.addColumn(ContactMessage::email).setHeader("Email");
+        grid.addColumn(ContactMessage::phone).setHeader("Phone");
+        grid.addColumn(ContactMessage::message).setHeader("Message");
+    }
+
+    private void refreshGrid() {
+        grid.setItems(contactMessageService.getMessages());
+    }
+
+    private void send() {
+        if (binder.validate().hasErrors()) {
+            return;
+        }
+
+        contactMessageService.send(nameField.getValue(), emailField.getValue(), phoneField.getValue(),
+                messageField.getValue());
+
+        clearForm();
+        sendButton.setEnabled(false);
+        refreshGrid();
+
+        Notification notification = Notification.show("Message sent");
+        notification.addThemeVariants(NotificationVariant.LUMO_SUCCESS);
+    }
+
+    private void clearForm() {
+        binder.readBean(null);
+    }
+
+    private boolean isFormEmpty() {
+        return isBlank(nameField.getValue()) && isBlank(emailField.getValue())
+                && isBlank(phoneField.getValue()) && isBlank(messageField.getValue());
+    }
+
+    private static boolean isBlank(String value) {
+        return value == null || value.isBlank();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!isFormEmpty()) {
+            BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+            confirmDiscard(action);
+        }
+    }
+
+    private void confirmDiscard(BeforeLeaveEvent.ContinueNavigationAction action) {
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        dialog.add(new Span("You have unsaved changes. Do you want to discard them?"));
+
+        Button keepEditing = new Button("Keep editing", event -> dialog.close());
+        Button discard = new Button("Discard", event -> {
+            dialog.close();
+            action.proceed();
+        });
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.open();
+    }
+}
